using Newtonsoft.Json.Linq;
namespace Cidonix.UniBridge.MCP.Editor.ToolRegistry
{
    // Complete source-return schemas with reviewed concrete identity/readback
    // producers. Authored JSON is confined to actual value and patch slots.
    internal static class InspectionActionOutputRules
    {
        internal static Dictionary<string,JObject> Build(string owner)
        {
            var document=JObject.Parse(Contracts);
            if(document["owners"]?[owner] is not JObject actions)throw new ArgumentOutOfRangeException(nameof(owner));
            var result=new Dictionary<string,JObject>(StringComparer.Ordinal);
            foreach(var action in actions.Properties())
            {
                var schema=(JObject)action.Value.DeepClone();
                schema["$defs"]=document["$defs"].DeepClone();
                result[action.Name]=schema;
            }
            if(owner=="UniBridge_ManageGameObject")
            {
                // The public pre-dispatch prefab redirection invokes the shipped
                // ManageAsset Modify handler and returns its complete response.
                var assetModify=GeneralAuthoringActionOutputRules.Build("UniBridge_ManageAsset")["Modify"];
                foreach(var name in new[]{"modify","set_component_property"})
                    result[name]=ActionOutputSchema.Compose(new[]{result[name],assetModify});
            }
            return result;
        }
